FROM destinations d
JOIN destination_translations dt ON d.id = dt.destination_id AND dt.language_code = 'ko'
JOIN country_categories cc ON d.region_id = cc.id
WHERE d.region_id IN

    #{id}



    AND d.type = #{destinationType}



    AND dt.name LIKE CONCAT('%', #{keyword}, '%')



    AND dt.name REGEXP #{chosungPattern}

mapper.select:
SELECT COALESCE(SUM(s.matchesVisibility), 0) AS total, COALESCE(SUM(s.hidden), 0) AS hidden, COALESCE(SUM(s.missingImage * s.matchesVisibility), 0) AS missingImage, COALESCE(SUM(s.missingMainImage * s.matchesVisibility), 0) AS missingMainImage, COALESCE(SUM(s.missingCategory * s.matchesVisibility), 0) AS missingCategory, COALESCE(SUM(s.missingTranslation * s.matchesVisibility), 0) AS missingTranslation, COALESCE(SUM(s.missingDescription * s.matchesVisibility), 0) AS missingDescription FROM ( SELECT d.is_public = 0 AS hidden,
d.is_public = #{publicVisible} 1 AS matchesVisibility, AS missingImage, AS missingMainImage, AS missingCategory, AS missingTranslation, AS missingDescription
) s

