SELECT c.id AS categoryId, COUNT(DISTINCT d.id) AS destinationCount FROM categories c LEFT JOIN destination_categories dc ON dc.category_id = c.id LEFT JOIN destinations d ON d.id = dc.destination_id AND d.is_public = 1 AND d.region_id IN
#{id}
GROUP BY c.id HAVING COUNT(DISTINCT d.id) > 0
OR c.id IN
